window.BOOK={"key":"mimiyya","app":"mutoon-mimiyya","lsk":"mutoon_mimiyya_v1","prefix":"mi_","title":"ميمية ابن القيم","sub":"التزكية والرقائق · ابن قيم الجوزية (ت ٧٥١هـ) · ٢٣٠ بيتًا","poems":[{"id":"mimiyya","title":"ميمية ابن القيم","nazim":"شمس الدين محمد بن أبي بكر ابن قيم الجوزية","death":"ت ٧٥١هـ","meter":"الطويل","source":"المكتبة الشاملة: القصيدة الميمية لابن قيم الجوزية (الرحلة إلى بلاد الأشواق)","srcUrl":"https://ketabonline.com/ar/books/54664","note":"نص «القصيدة الميمية» من المكتبة الشاملة بعناوين أقسامه، قوبل كلمةً كلمةً بسكربت بنص «شرح القصيدة الميمية» لسعد المزعل وبنص ويكي مصدر، وأُخذ من الشرح شطران سقطا من النشرة فصارت ٢٣٠ بيتًا. لم توجد نسخة رقمية مشكولة شكلًا تامًا (النشرة مشكولة نحو النصف)، فأكمل الذكاء الاصطناعي الشكل على حركات المصدرين والوزن، وكل شطر موزون على الطويل، ويحسن مراجعته على طبعة محققة.","verses":[["إِذَا طَلَعَتْ شَمْسُ النَّهَارِ فَإِنَّهَا","أَمَارَةُ تَسْلِيمِي عَلَيْكُمْ فَسَلِّمُوا"],["سَلَامٌ مِنَ الرَّحْمَنِ فِي كُلِّ سَاعَةٍ","وَرَوْحٌ وَرَيْحَانٌ وَفَضْلٌ وَأَنْعُمُ"],["عَلَى الصَّحْبِ وَالْإِخْوَانِ وَالْوِلْدِ وَالْأُلَى","دَعَوْهُمْ بِإِحْسَانٍ فَجَادُوا وَأَنْعَمُوا"],["وَسَائِرِ مَنْ لِلسُّنَّةِ الْمَحْضَةِ اقْتَفَى","وَمَا زَاغَ عَنْهَا فَهْوَ حَقٌّ مُقَدَّمُ"],["أُولَئِكَ أَتْبَاعُ النَّبِيِّ وَحِزْبُهُ","وَلَوْلَاهُمُ مَا كَانَ فِي الْأَرْضِ مُسْلِمُ"],["وَلَوْلَاهُمُ كَادَتْ تَمِيدُ بِأَهْلِهَا","وَلَكِنْ رَوَاسِيهَا وَأَوْتَادُهَا هُمُ"],["وَلَوْلَاهُمُ كَانَتْ ظَلَامًا بِأَهْلِهَا","وَلَكِنْ هُمُ فِيهَا بُدُورٌ وَأَنْجُمُ"],["أُولَئِكَ أَصْحَابِي فَحَيَّ هَلًا بِهِمْ","وَحَيَّ هَلًا بِالطَّيِّبِينَ وَأَنْعِمُ"],["لِكُلِّ امْرِئٍ مِنْهُمْ سَلَامٌ يَخُصُّهُ","يُبَلِّغُهُ الْأَدْنَى إِلَيْهِ وَيَنْعَمُ"],["فَيَا مُحْسِنًا بَلِّغْ سَلَامِي وَقُلْ لَهُمْ","مُحِبُّكُمُ يَدْعُو لَكُمْ وَيُسَلِّمُ"],["وَيَا لَائِمِي فِي حُبِّهِمْ وَوَلَائِهِمْ","تَأَمَّلْ هَدَاكَ اللَّهُ مَنْ هُوَ أَلْوَمُ"],["بِأَيِّ دَلِيلٍ أَمْ بِأَيَّةِ حُجَّةٍ","تَرَى حُبَّهُمْ عَارًا عَلَيَّ وَتَنْقِمُ"],["وَمَا الْعَارُ إِلَّا بُغْضُهُمْ وَاجْتِنَابُهُمْ","وَحُبُّ عِدَاهُمْ ذَاكَ عَارٌ وَمَأْثَمُ"],["أَمَا وَالَّذِي شَقَّ الْقُلُوبَ وَأَوْدَعَ الْـ","ـمَحَبَّةَ فِيهَا حَيْثُ لَا تَتَصَرَّمُ"],["وَحَمَّلَهَا قَلْبَ الْمُحِبِّ وَإِنَّهُ","لَيَضْعُفُ عَنْ حَمْلِ الْقَمِيصِ وَيَأْلَمُ"],["وَذَلَّلَهَا حَتَّى اسْتَكَانَتْ لِصَوْلَةِ الْـ","ـمَحَبَّةِ لَا تَلْوِي وَلَا تَتَلَعْثَمُ"],["وَذَلَّلَ فِيهَا أَنْفُسًا دُونَ ذُلِّهَا","حِيَاضُ الْمَنَايَا فَوْقَهَا وَهْيَ حُوَّمُ"],["لَأَنْتُمْ عَلَى قُرْبِ الدِّيَارِ وَبُعْدِهَا","أَحِبَّتُنَا إِنْ غِبْتُمُ أَوْ حَضَرْتُمُ"],["سَلُوا نَسَمَاتِ الرِّيحِ كَمْ قَدْ تَحَمَّلَتْ","مَحَبَّةَ صَبٍّ شَوْقُهُ لَيْسَ يُكْتَمُ"],["وَشَاهِدُ هَذَا أَنَّهَا فِي هُبُوبِهَا","تَكَادُ تَبُثُّ الْوَجْدَ لَوْ تَتَكَلَّمُ"],["وَكُنْتُ إِذَا مَا اشْتَدَّ بِي الشَّوْقُ وَالْجَوَى","وَكَادَتْ عُرَى الصَّبْرِ الْجَمِيلِ تَفَصَّمُ"],["أُعَلِّلُ نَفْسِي بِالتَّلَاقِي وَقُرْبِهِ","وَأُوهِمُهَا لَكِنَّهَا تَتَوَهَّمُ"],["وَأُتْبِعُ طَرْفِي وِجْهَةً أَنْتُمُ بِهَا","فَلِي بِحِمَاهَا مَرْبَعٌ وَمُخَيَّمُ"],["وَأَذْكُرُ بَيْتًا قَالَهُ بَعْضُ مَنْ خَلَا","وَقَدْ ضَلَّ عَنْهُ صَبْرُهُ فَهْوَ مُغْرَمُ"],["أُسَائِلُ عَنْكُمْ كُلَّ غَادٍ وَرَائِحٍ","وَأُومِي إِلَى أَوْطَانِكُمْ وَأُسَلِّمُ"],["وَكَمْ يَصْبِرُ الْمُشْتَاقُ عَمَّنْ يُحِبُّهُ","وَفِي قَلْبِهِ نَارُ الْأَسَى تَتَضَرَّمُ"],["أَمَا وَالَّذِي حَجَّ الْمُحِبُّونَ بَيْتَهُ","وَلَبَّوْا لَهُ عِنْدَ الْمَهَلِّ وَأَحْرَمُوا"],["وَقَدْ كَشَفُوا تِلْكَ الرُّؤُوسَ تَوَاضُعًا","لِعِزَّةِ مَنْ تَعْنُو الْوُجُوهُ وَتُسْلِمُ"],["يُهِلُّونَ بِالْبَيْدَاءِ لَبَّيْكَ رَبَّنَا","لَكَ الْمُلْكُ وَالْحَمْدُ الَّذِي أَنْتَ تَعْلَمُ"],["دَعَاهُمْ فَلَبَّوْهُ رِضًا وَمَحَبَّةً","فَلَمَّا دَعَوْهُ كَانَ أَقْرَبَ مِنْهُمُ"],["تَرَاهُمْ عَلَى الْأَنْضَاءِ شُعْثًا رُؤُوسُهُمْ","وَغُبْرًا وَهُمْ فِيهَا أَسَرُّ وَأَنْعَمُ"],["وَقَدْ فَارَقُوا الْأَوْطَانَ وَالْأَهْلَ رَغْبَةً","وَلَمْ يُثْنِهِمْ لَذَّاتُهُمْ وَالتَّنَعُّمُ"],["يَسِيرُونَ مِنْ أَقْطَارِهَا وَفِجَاجِهَا","رِجَالًا وَرُكْبَانًا وَلِلَّهِ أَسْلَمُوا"],["وَلَمَّا رَأَتْ أَبْصَارُهُمْ بَيْتَهُ الَّذِي","قُلُوبُ الْوَرَى شَوْقًا إِلَيْهِ تَضَرَّمُ"],["كَأَنَّهُمُ لَمْ يَنْصَبُوا قَطُّ قَبْلَهُ","لِأَنَّ شَقَاهُمْ قَدْ تَرَحَّلَ عَنْهُمُ"],["فَلِلَّهِ كَمْ مِنْ عَبْرَةٍ مُهَرَاقَةٍ","وَأُخْرَى عَلَى آثَارِهَا لَا تَقَدَّمُ"],["وَقَدْ شَرِقَتْ عَيْنُ الْمُحِبِّ بِدَمْعِهَا","فَيَنْظُرُ مِنْ بَيْنِ الدُّمُوعِ وَيُسْجِمُ"],["إِذَا عَايَنَتْهُ الْعَيْنُ زَالَ ظَلَامُهَا","وَزَالَ عَنِ الْقَلْبِ الْكَئِيبِ التَّأَلُّمُ"],["وَلَا يَعْرِفُ الطَّرْفُ الْمُعَايِنُ حُسْنَهُ","إِلَى أَنْ يَعُودَ الطَّرْفُ وَالشَّوْقُ أَعْظَمُ"],["وَلَا عَجَبٌ مِنْ ذَا فَحِينَ أَضَافَهُ","إِلَى نَفْسِهِ الرَّحْمَنُ فَهْوَ الْمُعَظَّمُ"],["كَسَاهُ مِنَ الْإِجْلَالِ أَعْظَمَ حُلَّةٍ","عَلَيْهَا طِرَازٌ بِالْمَلَاحَةِ مُعْلَمُ"],["فَمِنْ أَجْلِ ذَا كُلُّ الْقُلُوبِ تُحِبُّهُ","وَتَخْضَعُ إِجْلَالًا لَهُ وَتُعَظِّمُ"],["وَرَاحُوا إِلَى التَّعْرِيفِ يَرْجُونَ رَحْمَةً","وَمَغْفِرَةً مِمَّنْ يَجُودُ وَيُكْرِمُ"],["فَلِلَّهِ ذَاكَ الْمَوْقِفُ الْأَعْظَمُ الَّذِي","كَمَوْقِفِ يَوْمِ الْعَرْضِ بَلْ ذَاكَ أَعْظَمُ"],["وَيَدْنُو بِهِ الْجَبَّارُ جَلَّ جَلَالُهُ","يُبَاهِي بِهِمْ أَمْلَاكَهُ فَهْوَ أَكْرَمُ"],["يَقُولُ عِبَادِي قَدْ أَتَوْنِي مَحَبَّةً","وَإِنِّي بِهِمْ بَرٌّ أَجُودُ وَأَرْحَمُ"],["فَأُشْهِدُكُمْ أَنِّي غَفَرْتُ ذُنُوبَهُمْ","وَأَعْطَيْتُهُمْ مَا أَمَّلُوهُ وَأُنْعِمُ"],["فَبُشْرَاكُمُ يَا أَهْلَ ذَا الْمَوْقِفِ الَّذِي","بِهِ يَغْفِرُ اللَّهُ الذُّنُوبَ وَيَرْحَمُ"],["فَكَمْ مِنْ عَتِيقٍ فِيهِ كُمِّلَ عِتْقُهُ","وَآخَرَ يُسْتَسْعَى وَرَبُّكَ أَرْحَمُ"],["وَمَا رُئِيَ الشَّيْطَانُ أَغْيَظَ فِي الْوَرَى","وَأَحْقَرَ مِنْهُ عِنْدَهَا وَهْوَ أَلْأَمُ"],["وَذَاكَ لِأَمْرٍ قَدْ رَآهُ فَغَاظَهُ","فَأَقْبَلَ يَحْثُو التُّرْبَ غَيْظًا وَيَلْطِمُ"],["وَمَا عَايَنَتْ عَيْنَاهُ مِنْ رَحْمَةٍ أَتَتْ","وَمَغْفِرَةٍ مِنْ عِنْدِ ذِي الْعَرْشِ تُقْسَمُ"],["بَنَى مَا بَنَى حَتَّى إِذَا ظَنَّ أَنَّهُ","تَمَكَّنَ مِنْ بُنْيَانِهِ فَهْوَ مُحْكَمُ"],["أَتَى اللَّهُ بُنْيَانًا لَهُ مِنْ أَسَاسِهِ","فَخَرَّ عَلَيْهِ سَاقِطًا يَتَهَدَّمُ"],["وَكَمْ قَدْرُ مَا يَعْلُو الْبِنَاءُ وَيَنْتَهِي","إِذَا كَانَ يَبْنِيهِ وَذُو الْعَرْشِ يَهْدِمُ"],["وَرَاحُوا إِلَى جَمْعٍ فَبَاتُوا بِمَشْعَرِ الْـ","ـحَرَامِ وَصَلَّوْا الْفَجْرَ ثُمَّ تَقَدَّمُوا"],["إِلَى الْجَمْرَةِ الْكُبْرَى يُرِيدُونَ رَمْيَهَا","لِوَقْتِ صَلَاةِ الْعِيدِ ثُمَّ تَيَمَّمُوا"],["مَنَازِلَهُمْ لِلنَّحْرِ يَبْغُونَ فَضْلَهُ","وَإِحْيَاءَ نُسْكٍ مِنْ أَبِيهِمْ يُعَظَّمُ"],["فَلَوْ كَانَ يُرْضِي اللَّهَ نَحْرُ نُفُوسِهِمْ","لَدَانُوا بِهِ طَوْعًا وَلِلْأَمْرِ سَلَّمُوا"],["كَمَا بَذَلُوا عِنْدَ الْجِهَادِ نُحُورَهُمْ","لِأَعْدَائِهِ حَتَّى جَرَى مِنْهُمُ الدَّمُ"],["وَلَكِنَّهُمْ دَانُوا بِوَضْعِ رُؤُوسِهِمْ","وَذَلِكَ ذُلٌّ لِلْعَبِيدِ وَمِيسَمُ"],["وَلَمَّا تَقَضَّوْا ذَلِكَ التَّفَثَ الَّذِي","عَلَيْهِمْ وَأَوْفَوْا نَذْرَهُمْ ثُمَّ تَمَّمُوا"],["دَعَاهُمْ إِلَى الْبَيْتِ الْعَتِيقِ زِيَارَةً","فَيَا مَرْحَبًا بِالزَّائِرِينَ وَأَكْرِمُ"],["فَلِلَّهِ مَا أَبْهَى زِيَارَتَهُمْ لَهُ","وَقَدْ حُصِّلَتْ تِلْكَ الْجَوَائِزُ تُقْسَمُ"],["وَلِلَّهِ أَفْضَالٌ هُنَاكَ وَنِعْمَةٌ","وَبِرٌّ وَإِحْسَانٌ وَجُودٌ وَمَرْحَمُ"],["وَعَادُوا إِلَى تِلْكَ الْمَنَازِلِ مِنْ مِنًى","وَنَالُوا مُنَاهُمْ عِنْدَهَا وَتَنَعَّمُوا"],["أَقَامُوا بِهَا يَوْمًا وَيَوْمًا وَثَالِثًا","وَأُذِّنَ فِيهِمْ بِالرَّحِيلِ وَأُعْلِمُوا"],["وَرَاحُوا إِلَى رَمْيِ الْجِمَارِ عَشِيَّةً","شِعَارُهُمُ التَّكْبِيرُ وَاللَّهُ مَعْهُمُ"],["فَلَوْ أَبْصَرَتْ عَيْنَاكَ مَوْقِفَهُمْ بِهَا","وَقَدْ بَسَطُوا تِلْكَ الْأَكُفَّ لِيُرْحَمُوا"],["يُنَادُونَهُ يَا رَبِّ يَا رَبِّ إِنَّنَا","عَبِيدُكَ لَا نَدْعُو سِوَاكَ وَتَعْلَمُ"],["وَهَا نَحْنُ نَرْجُو مِنْكَ مَا أَنْتَ أَهْلُهُ","فَأَنْتَ الَّذِي تُعْطِي الْجَزِيلَ وَتُنْعِمُ"],["وَلَمَّا تَقَضَّوْا مِنْ مِنًى كُلَّ حَاجَةٍ","وَسَالَتْ بِهِمْ تِلْكَ الْبِطَاحُ تَقَدَّمُوا"],["إِلَى الْكَعْبَةِ الْبَيْتِ الْحَرَامِ عَشِيَّةً","وَطَافُوا بِهَا سَبْعًا وَصَلَّوْا وَسَلَّمُوا"],["وَلَمَّا دَنَا التَّوْدِيعُ مِنْهُمْ وَأَيْقَنُوا","بِأَنَّ التَّدَانِي حَبْلُهُ مُتَصَرِّمُ"],["وَلَمْ يَبْقَ إِلَّا وَقْفَةٌ لِمُوَدِّعٍ","فَلِلَّهِ أَجْفَانٌ هُنَاكَ تُسَجَّمُ"],["وَلِلَّهِ أَكْبَادٌ هُنَالِكَ أُودِعَ الْـ","ـغَرَامُ بِهَا فَالنَّارُ فِيهَا تَضَرَّمُ"],["وَلِلَّهِ أَنْفَاسٌ يَكَادُ بِحَرِّهَا","يَذُوبُ الْمُحِبُّ الْمُسْتَهَامُ الْمُتَيَّمُ"],["فَلَمْ تَرَ إِلَّا بَاهِتًا مُتَحَيِّرًا","وَآخَرَ يُبْدِي شَجْوَهُ يَتَرَنَّمُ"],["رَحَلْتُ وَأَشْوَاقِي إِلَيْكُمْ مُقِيمَةٌ","وَنَارُ الْأَسَى مِنِّي تَشِبُّ وَتَضْرِمُ"],["أُوَدِّعُكُمْ وَالشَّوْقُ يَثْنِي أَعِنَّتِي","وَقَلْبِيَ أَمْسَى فِي حِمَاكُمْ مُخَيِّمُ"],["هُنَالِكَ لَا تَثْرِيبَ يَوْمًا عَلَى امْرِئٍ","إِذَا مَا بَدَا مِنْهُ الَّذِي كَانَ يَكْتُمُ"],["فَيَا سَائِقِينَ الْعِيسَ بِاللَّهِ رَبِّكُمْ","قِفُوا لِي عَلَى تِلْكَ الرُّبُوعِ وَسَلِّمُوا"],["وَقُولُوا مُحِبٌّ قَادَهُ الشَّوْقُ نَحْوَكُمْ","قَضَى نَحْبَهُ فِيكُمْ تَعِيشُوا وَتَسْلَمُوا"],["قَضَى اللَّهُ رَبُّ الْعَرْشِ فِيمَا قَضَى بِهِ","بِأَنَّ الْهَوَى يُعْمِي الْقُلُوبَ وَيُبْكِمُ"],["وَحُبُّكُمُ أَصْلُ الْهَوَى وَمَدَارُهُ","عَلَيْهِ وَفَوْزٌ لِلْمُحِبِّ وَمَغْنَمُ"],["وَتَفْنَى عِظَامُ الصَّبِّ بَعْدَ مَمَاتِهِ","وَأَشْوَاقُهُ وَقْفٌ عَلَيْهِ مُحَرَّمُ"],["فَيَا أَيُّهَا الْقَلْبُ الَّذِي مَلَكَ الْهَوَى","أَزِمَّتَهُ حَتَّى مَتَى ذَا التَّلَوُّمُ"],["وَحَتَّامَ لَا تَصْحُو وَقَدْ قَرُبَ الْمَدَى","وَدَانَتْ كُؤُوسُ السَّيْرِ وَالنَّاسُ نُوَّمُ"],["بَلَى سَوْفَ تَصْحُو حِينَ يَنْكَشِفُ الْغِطَا","وَيَبْدُو لَكَ الْأَمْرُ الَّذِي أَنْتَ تَكْتُمُ"],["وَيَا مُوقِدًا نَارًا لِغَيْرِكَ ضَوْؤُهَا","وَحَرُّ لَظَاهَا بَيْنَ جَنْبَيْكَ يَضْرِمُ"],["أَهَذَا جَنَى الْعِلْمِ الَّذِي قَدْ غَرَسْتَهُ","وَهَذَا الَّذِي قَدْ كُنْتَ تَرْجُوهُ يُطْعِمُ"],["وَهَذَا هُوَ الْحَظُّ الَّذِي قَدْ رَضِيتَهُ","لِنَفْسِكَ فِي الدَّارَيْنِ جَاهٌ وَدِرْهَمُ"],["وَهَذَا هُوَ الرِّبْحُ الَّذِي قَدْ كَسَبْتَهُ","لَعَمْرُكَ لَا رِبْحٌ وَلَا الْأَصْلُ يَسْلَمُ"],["بَخِلْتَ بِشَيْءٍ لَا يَضُرُّكَ بَذْلُهُ","وَجُدْتَ بِشَيْءٍ مِثْلُهُ لَا يُقَوَّمُ"],["بَخِلْتَ بِذَا الْحَظِّ الْخَسِيسِ دَنَاءَةً","وَجُدْتَ بِدَارِ الْخُلْدِ لَوْ كُنْتَ تَفْهَمُ"],["وَبِعْتَ نَعِيمًا لَا انْقِضَاءَ لَهُ وَلَا","نَظِيرَ بِبَخْسٍ عَنْ قَلِيلٍ سَيُعْدَمُ"],["فَهَلَّا عَكَسْتَ الْأَمْرَ إِنْ كُنْتَ حَازِمًا","وَلَكِنْ أَضَعْتَ الْحَزْمَ لَوْ كُنْتَ تَعْلَمُ"],["وَتَهْدِمُ مَا تَبْنِي بِكَفِّكَ جَاهِدًا","فَأَنْتَ مَدَى الْأَيَّامِ تَبْنِي وَتَهْدِمُ"],["وَعِنْدَ مُرَادِ اللَّهِ تَفْنَى كَمَيِّتٍ","وَعِنْدَ مُرَادِ النَّفْسِ تُسْدِي وَتُلْحِمُ"],["وَعِنْدَ خِلَافِ الْأَمْرِ تَحْتَجُّ بِالْقَضَا","ظَهِيرًا عَلَى الرَّحْمَنِ لِلْجَبْرِ تَزْعُمُ"],["تُنَزِّهُ مِنْكَ النَّفْسَ عَنْ سُوءِ فِعْلِهَا","وَتَعْتِبُ أَقْدَارَ الْإِلَهِ وَتَظْلِمُ"],["تُحِلُّ أُمُورًا أَحْكَمَ الشَّرْعُ عَقْدَهَا","وَتَقْصِدُ مَا قَدْ حَلَّهُ الشَّرْعُ تُبْرِمُ"],["وَتَفْهَمُ مِنْ قَوْلِ الرَّسُولِ خِلَافَ مَا","أَرَادَ لِأَنَّ الْقَلْبَ مِنْكَ مُعَجَّمُ"],["مُطِيعٌ لِدَاعِي الْغَيِّ عَاصٍ لِرُشْدِهِ","إِلَى رَبِّهِ يَوْمًا يُرَدُّ وَيَعْلَمُ"],["مُضِيعٌ لِأَمْرِ اللَّهِ قَدْ غَشَّ نَفْسَهُ","مُهِينٌ لَهَا أَنَّى يُحَبُّ وَيُكْرَمُ"],["بَطِيءٌ عَنِ الطَّاعَاتِ أَسْرَعُ لِلْخَنَا","مِنَ السَّيْلِ فِي مَجْرَاهُ لَا يَتَقَسَّمُ"],["وَتَزْعُمُ مَعْ هَذَا بِأَنَّكَ عَارِفٌ","كَذَبْتَ يَقِينًا فِي الَّذِي أَنْتَ تَزْعُمُ"],["وَمَا أَنْتَ إِلَّا جَاهِلٌ ثُمَّ ظَالِمٌ","وَإِنَّكَ بَيْنَ الْجَاهِلِينَ مُقَدَّمُ"],["إِذَا كَانَ هَذَا نُصْحَ عَبْدٍ لِنَفْسِهِ","فَمَنْ ذَا الَّذِي مِنْهُ الْهُدَى يُتَعَلَّمُ"],["وَفِي مِثْلِ هَذَا الْحَالِ قَدْ قَالَ مَنْ مَضَى","وَأَحْسَنَ فِيمَا قَالَهُ الْمُتَكَلِّمُ"],["فَإِنْ كُنْتَ لَا تَدْرِي فَتِلْكَ مُصِيبَةٌ","وَإِنْ كُنْتَ تَدْرِي فَالْمُصِيبَةُ أَعْظَمُ"],["وَلَوْ تُبْصِرُ الدُّنْيَا وَرَاءَ سُتُورِهَا","رَأَيْتَ خَيَالًا فِي مَنَامٍ سَيُصْرَمُ"],["كَحُلْمٍ بِطَيْفٍ زَارَ فِي النَّوْمِ وَانْقَضَى الْـ","ـمَنَامُ وَرَاحَ الطَّيْفُ وَالصَّبُّ مُغْرَمُ"],["وَظِلٍّ أَتَتْهُ الشَّمْسُ عِنْدَ طُلُوعِهَا","سَيَقْلِصُ فِي وَقْتِ الزَّوَالِ وَيُفْصَمُ"],["وَمُزْنَةِ صَيْفٍ طَابَ مِنْهَا مَقِيلُهَا","فَوَلَّتْ سَرِيعًا وَالْحَرُورُ تَضَرَّمُ"],["وَمَطْعَمِ ضَيْفٍ لَذَّ مِنْهُ مَسَاغُهُ","وَبَعْدَ قَلِيلٍ حَالُهُ تِلْكَ تُعْلَمُ"],["كَذَا هَذِهِ الدُّنْيَا كَأَحْلَامِ نَائِمٍ","وَمِنْ بَعْدِهَا دَارُ الْبَقَاءِ سَتُقْدِمُ"],["فَجُزْهَا مَمَرًّا لَا مَقَرًّا وَكُنْ بِهَا","غَرِيبًا تَعِشْ فِيهَا حَمِيدًا وَتَسْلَمُ"],["أَوِ ابْنَ سَبِيلٍ قَالَ فِي ظِلِّ دَوْحَةٍ","وَرَاحَ وَخَلَّى ظِلَّهَا يَتَقَسَّمُ"],["أَخَا سَفَرٍ لَا يَسْتَقِرُّ قَرَارُهُ","إِلَى أَنْ يَرَى أَوْطَانَهُ وَيُسَلِّمُ"],["فَيَا عَجَبًا كَمْ مَصْرَعٍ وَعَظَتْ بِهِ","بَنِيهَا وَلَكِنْ عَنْ مَصَارِعِهَا عَمُوا"],["سَقَتْهُمْ كُؤُوسَ الْحُبِّ حَتَّى إِذَا نَشَوْا","سَقَتْهُمْ كُؤُوسَ السُّمِّ وَالْقَوْمُ نُوَّمُ"],["وَأَعْجَبُ مَا فِي الْعَبْدِ رُؤْيَةُ هَذِهِ الْـ","ـعَظَائِمِ وَالْمَغْمُورُ فِيهَا مُتَيَّمُ"],["وَمَا ذَاكَ إِلَّا أَنَّ خَمْرَةَ حُبِّهَا","لَتَسْلُبُ عَقْلَ الْمَرْءِ مِنْهُ وَتَصْلِمُ"],["وَأَعْجَبُ مِنْ ذَا أَنَّ أَحْبَابَهَا الْأُلَى","تُهِينُ وَلِلْأَعْدَا تُرَاعِي وَتُكْرِمُ"],["وَذَلِكَ بُرْهَانٌ عَلَى أَنَّ قَدْرَهَا","جَنَاحُ بَعُوضٍ أَوْ أَدَقُّ وَأَلْأَمُ"],["وَحَسْبُكَ مَا قَالَ الرَّسُولُ مُمَثِّلًا","لَهَا وَلِدَارِ الْخُلْدِ وَالْحَقُّ يُفْهَمُ"],["كَمَا يُدْلِيَ الْإِنْسَانُ فِي الْيَمِّ أُصْبُعًا","وَيَنْزِعُهَا عَنْهُ فَمَا ذَاكَ يَغْنَمُ"],["أَلَا لَيْتَ شِعْرِي هَلْ أَبِيتَنَّ لَيْلَةً","عَلَى حَذَرٍ مِنْهَا وَأَمْرِيَ مُبْرَمُ"],["وَهَلْ أَرِدَنْ مَاءَ الْحَيَاةِ وَأَرْتَوِي","عَلَى ظَمَإٍ مِنْ حَوْضِهِ وَهْوَ مُفْعَمُ"],["وَهَلْ تَبْدُوَنْ أَعْلَامُهَا بَعْدَمَا سَفَتْ","عَلَى رَبْعِهَا تِلْكَ السَّوَافِي فَتُعْلَمُ"],["وَهَلْ أَفْرِشَنْ خَدِّي ثَرَى عَتَبَاتِهِمْ","خُضُوعًا لَهُمْ كَيْمَا يَرِقُّوا وَيَرْحَمُوا"],["وَهَلْ أَرْمِيَنْ نَفْسِي طَرِيحًا بِبَابِهِمْ","وَطَيْرُ مَنَايَا الْحُبِّ فَوْقِي تُحَوِّمُ"],["فَيَا أَسَفِي تَفْنَى الْحَيَاةُ وَتَنْقَضِي","وَذَا الْعَتْبُ بَاقٍ مَا بَقِيتُمْ وَعِشْتُمُ"],["فَمَا مِنْكُمُ بُدٌّ وَلَا عَنْكُمُ غِنًى","وَمَا لِيَ مِنْ صَبْرٍ فَأَسْلُوَ عَنْكُمُ"],["وَمَنْ شَاءَ فَلْيَغْضَبْ سِوَاكُمْ فَلَا أَذًى","إِذَا كُنْتُمُ عَنْ عَبْدِكُمْ قَدْ رَضِيتُمُ"],["وَعُقْبَى اصْطِبَارِي فِي هَوَاكُمْ حَمِيدَةٌ","وَلَكِنَّهَا عَنْكُمْ عِقَابٌ وَمَأْثَمُ"],["وَمَا أَنَا بِالشَّاكِي لِمَا تَرْتَضُونَهُ","وَلَكِنَّنِي أَرْضَى بِهِ وَأُسَلِّمُ"],["وَحَسْبِي انْتِسَابِي مِنْ بُعَيْدٍ إِلَيْكُمُ","أَلَا إِنَّهُ حَظٌّ عَظِيمٌ مُفَخَّمُ"],["إِذَا قِيلَ هَذَا عَبْدُهُمْ وَمُحِبُّهُمْ","تَهَلَّلَ بِشْرًا وَجْهُهُ يَتَبَسَّمُ"],["وَهَا هُوَ قَدْ أَبْدَى الضَّرَاعَةَ سَائِلًا","لَكُمْ بِلِسَانِ الْحَالِ وَالْقَالِ مُعْلِمُ"],["أَحِبَّتَهُ عَطْفًا عَلَيْهِ فَإِنَّهُ","لَفِي ظَمَإٍ وَالْمَوْرِدُ الْعَذْبُ أَنْتُمُ"],["فَيَا سَاهِيًا فِي غَمْرَةِ الْجَهْلِ وَالْهَوَى","صَرِيعَ الْأَمَانِي عَنْ قَرِيبٍ سَتَنْدَمُ"],["أَفِقْ قَدْ دَنَا الْوَقْتُ الَّذِي لَيْسَ بَعْدَهُ","سِوَى جَنَّةٍ أَوْ حَرِّ نَارٍ تَضَرَّمُ"],["وَبِالسُّنَّةِ الْغَرَّاءِ كُنْ مُتَمَسِّكًا","هِيَ الْعُرْوَةُ الْوُثْقَى الَّتِي لَيْسَ تُفْصَمُ"],["تَمَسَّكْ بِهَا مَسْكَ الْبَخِيلِ بِمَالِهِ","وَعَضَّ عَلَيْهَا بِالنَّوَاجِذِ تَسْلَمُ"],["وَدَعْ عَنْكَ مَا قَدْ أَحْدَثَ النَّاسُ بَعْدَهَا","فَمَرْتَعُ هَاتِيكَ الْحَوَادِثِ أَوْخَمُ"],["وَهَيِّئْ جَوَابًا عِنْدَمَا تَسْمَعُ النِّدَا","مِنَ اللَّهِ يَوْمَ الْعَرْضِ مَاذَا أَجَبْتُمُ"],["بِهِ رُسُلِي لَمَّا أَتَوْكُمْ فَمَنْ يَكُنْ","أَجَابَ سِوَاهُمْ سَوْفَ يُخْزَى وَيَنْدَمُ"],["وَخُذْ مِنْ تُقَى الرَّحْمَنِ أَعْظَمَ جُنَّةٍ","لِيَوْمٍ بِهِ تَبْدُو عِيَانًا جَهَنَّمُ"],["وَيُنْصَبُ ذَاكَ الْجِسْرُ مِنْ فَوْقِ مَتْنِهَا","فَهَاوٍ وَمَخْدُوشٌ وَنَاجٍ مُسَلَّمُ"],["وَيَأْتِي إِلَهُ الْعَالَمِينَ لِوَعْدِهِ","فَيَفْصِلُ مَا بَيْنَ الْعِبَادِ وَيَحْكُمُ"],["وَيَأْخُذُ لِلْمَظْلُومِ رَبُّكَ حَقَّهُ","فَيَا بُؤْسَ عَبْدٍ لِلْخَلَائِقِ يَظْلِمُ"],["وَيُنْشَرُ دِيوَانُ الْحِسَابِ وَتُوضَعُ الْـ","ـمَوَازِينُ بِالْقِسْطِ الَّذِي لَيْسَ يَظْلِمُ"],["فَلَا مُجْرِمٌ يَخْشَى ظُلَامَةَ ذَرَّةٍ","وَلَا مُحْسِنٌ مِنْ أَجْرِهِ ذَاكَ يُهْضَمُ"],["وَتَشْهَدُ أَعْضَاءُ الْمُسِيءِ بِمَا جَنَى","كَذَاكَ عَلَى فِيهِ الْمُهَيْمِنُ يَخْتِمُ"],["فَيَا لَيْتَ شِعْرِي كَيْفَ حَالُكَ عِنْدَمَا","تَطَايَرُ كُتْبُ الْعَالَمِينَ وَتُقْسَمُ"],["أَتَأْخُذُ بِالْيُمْنَى كِتَابَكَ أَمْ تَكُنْ","بِالُاخْرَى وَرَاءَ الظَّهْرِ مِنْكَ تُسَلَّمُ"],["وَتَقْرَأُ فِيهِ كُلَّ شَيْءٍ عَمِلْتَهُ","فَيُشْرِقُ مِنْكَ الْوَجْهُ أَوْ هُوَ يُظْلِمُ"],["تَقُولُ كِتَابِي فَاقْرَؤُوهُ فَإِنَّهُ","يُبَشِّرُ بِالْفَوْزِ الْعَظِيمِ وَيُعْلِمُ"],["وَإِنْ تَكُنِ الْأُخْرَى فَإِنَّكَ قَائِلٌ","أَلَا لَيْتَنِي لَمْ أُوتَهُ فَهْوَ مُغْرَمُ"],["فَبَادِرْ إِذَا مَا دَامَ فِي الْعُمْرِ فُسْحَةٌ","وَعَدْلُكَ مَقْبُولٌ وَصَرْفُكَ قَيِّمُ"],["وَجِدَّ وَسَارِعْ وَاغْتَنِمْ زَمَنَ الصِّبَا","فَفِي زَمَنِ الْإِمْكَانِ تَسْعَى وَتَغْنَمُ"],["وَسِرْ مُسْرِعًا فَالْمَوْتُ خَلْفَكَ مُسْرِعٌ","وَهَيْهَاتَ مَا مِنْهُ مَفَرٌّ وَمَهْزَمُ"],["فَهُنَّ الْمَنَايَا أَيَّ وَادٍ نَزَلْتَهُ","عَلَيْهَا الْقُدُومُ أَوْ عَلَيْكَ سَتَقْدَمُ"],["وَمَا ذَاكَ إِلَّا غَيْرَةً أَنْ يَنَالَهَا","سِوَى كُفْئِهَا وَالرَّبُّ بِالْخَلْقِ أَعْلَمُ"],["وَإِنْ حُجِبَتْ عَنَّا بِكُلِّ كَرِيهَةٍ","وَحُفَّتْ بِمَا يُؤْذِي النُّفُوسَ وَيُؤْلِمُ"],["فَلِلَّهِ مَا فِي حَشْوِهَا مِنْ مَسَرَّةٍ","وَأَصْنَافِ لَذَّاتٍ بِهَا نَتَنَعَّمُ"],["وَلِلَّهِ بَرْدُ الْعَيْشِ بَيْنَ خِيَامِهَا","وَرَوْضَاتِهَا وَالثَّغْرُ فِي الرَّوْضِ يَبْسِمُ"],["فَلِلَّهِ وَادِيهَا الَّذِي هُوَ مَوْعِدُ الْـ","ـمَزِيدِ لِوَفْدِ الْحُبِّ لَوْ كُنْتَ مِنْهُمُ"],["بِذَيَّالِكَ الْوَادِي يَهِيمُ صَبَابَةً","مُحِبٌّ يَرَى أَنَّ الصَّبَابَةَ مَغْنَمُ"],["وَلِلَّهِ أَفْرَاحُ الْمُحِبِّينَ عِنْدَمَا","يُخَاطِبُهُمْ مِنْ فَوْقِهِمْ وَيُسَلِّمُ"],["وَلِلَّهِ أَبْصَارٌ تَرَى اللَّهَ جَهْرَةً","فَلَا الضَّيْمُ يَغْشَاهَا وَلَا هِيَ تَسْأَمُ"],["فَيَا نَظْرَةً أَهْدَتْ إِلَى الْوَجْهِ نَضْرَةً","أَمِنْ بَعْدِهَا يَسْلُو الْمُحِبُّ الْمُتَيَّمُ"],["وَلِلَّهِ كَمْ مِنْ خَيْرَةٍ لَوْ تَبَسَّمَتْ","أَضَاءَ لَهَا نُورٌ مِنَ الْفَجْرِ أَعْظَمُ"],["فَيَا لَذَّةَ الْأَبْصَارِ إِنْ هِيَ أَقْبَلَتْ","وَيَا لَذَّةَ الْأَسْمَاعِ حِينَ تَكَلَّمُ"],["وَيَا خَجْلَةَ الْغُصْنِ الرَّطِيبِ إِذَا انْثَنَتْ","وَيَا خَجْلَةَ الْبَحْرَيْنِ حِينَ تَبَسَّمُ"],["فَإِنْ كُنْتَ ذَا قَلْبٍ عَلِيلٍ بِحُبِّهَا","فَلَمْ يَبْقَ إِلَّا وَصْلُهَا لَكَ مَرْهَمُ"],["وَلَا سِيَّمَا فِي لَثْمِهَا عِنْدَ ضَمِّهَا","وَقَدْ صَارَ مِنْهَا تَحْتَ جِيدِكَ مِعْصَمُ"],["يَرَاهَا إِذَا أَبْدَتْ لَهُ حُسْنَ وَجْهِهَا","يَلَذُّ بِهَا قَبْلَ الْوِصَالِ وَيَنْعَمُ"],["تَفَكَّهُ مِنْهَا الْعَيْنُ عِنْدَ اجْتِلَائِهَا","فَوَاكِهَ شَتَّى طَلْعُهَا لَيْسَ يُعْدَمُ"],["عَنَاقِدَ مِنْ كَرْمٍ وَتُفَّاحَ جَنَّةٍ","وَرُمَّانَ أَغْصَانٍ بِهَا الْقَلْبُ مُغْرَمُ"],["وَلِلْوَرْدِ مَا قَدْ أَلْبَسَتْهُ خُدُودُهَا","وَلِلْخَمْرِ مَا قَدْ ضَمَّهُ الرِّيقُ وَالْفَمُ"],["تَقَسَّمَ مِنْهَا الْحُسْنُ فِي جَمْعِ وَاحِدٍ","فَيَا عَجَبًا مِنْ وَاحِدٍ يَتَقَسَّمُ"],["لَهَا فِرَقٌ شَتَّى مِنَ الْحُسْنِ أَجْمَعَتْ","بِجُمْلَتِهَا أَنَّ السُّلُوَّ مُحَرَّمُ"],["تُذَكِّرُ بِالرَّحْمَنِ مَنْ هُوَ نَاظِرٌ","فَيَنْطِقُ بِالتَّسْبِيحِ لَا يَتَلَعْثَمُ"],["إِذَا قَابَلَتْ جَيْشَ الْهُمُومِ بِوَجْهِهَا","تَوَلَّى عَلَى أَعْقَابِهِ الْجَيْشُ يُهْزَمُ"],["وَلَمَّا جَرَى مَاءُ الشَّبَابِ بِغُصْنِهَا","تَيَقَّنَ حَقًّا أَنَّهُ لَيْسَ يَهْرَمُ"],["فَيَا خَاطِبَ الْحَسْنَاءِ إِنْ كُنْتَ رَاغِبًا","فَهَذَا زَمَانُ الْمَهْرِ فَهْوَ الْمُقَدَّمُ"],["وَكُنْ مُبْغِضًا لِلْخَائِنَاتِ لِحُبِّهَا","فَتَحْظَى بِهَا مِنْ دُونِهِنَّ وَتَنْعَمُ"],["وَكُنْ أَيِّمًا مِمَّا سِوَاهَا فَإِنَّهَا","لِمِثْلِكَ فِي جَنَّاتِ عَدْنٍ تَأَيَّمُ"],["وَصُمْ يَوْمَكَ الْأَدْنَى لَعَلَّكَ فِي غَدٍ","تَفُوزُ بِعِيدِ الْفِطْرِ وَالنَّاسُ صُوَّمُ"],["وَأَقْدِمْ وَلَا تَقْنَعْ بِعَيْشٍ مُنَغَّصٍ","فَمَا فَازَ بِاللَّذَّاتِ مَنْ لَيْسَ يُقْدِمُ"],["وَإِنْ ضَاقَتِ الدُّنْيَا عَلَيْكَ بِأَسْرِهَا","وَلَمْ يَكُ فِيهَا مَنْزِلٌ لَكَ يُعْلَمُ"],["فَحَيَّ عَلَى جَنَّاتِ عَدْنٍ فَإِنَّهَا","مَنَازِلُكَ الْأُولَى وَفِيهَا الْمُخَيَّمُ"],["وَلَكِنَّنَا سَبْيُ الْعَدُوِّ فَهَلْ تَرَى","نَعُودُ إِلَى أَوْطَانِنَا وَنُسَلَّمُ"],["وَقَدْ زَعَمُوا أَنَّ الْغَرِيبَ إِذَا نَأَى","وَشَطَّتْ بِهِ أَوْطَانُهُ فَهْوَ مُؤْلَمُ"],["وَأَيُّ اغْتِرَابٍ فَوْقَ غُرْبَتِنَا الَّتِي","لَهَا أَضْحَتِ الْأَعْدَاءُ فِينَا تَحَكَّمُ"],["وَحَيَّ عَلَى رَوْضَاتِهَا وَخِيَامِهَا","وَحَيَّ عَلَى عَيْشٍ بِهَا لَيْسَ يُسْأَمُ"],["وَحَيَّ عَلَى السُّوقِ الَّذِي فِيهِ يَلْتَقِي الْـ","ـمُحِبُّونَ ذَاكَ السُّوقُ لِلْقَوْمِ يُعْلَمُ"],["فَمَا شِئْتَ خُذْ مِنْهُ بِلَا ثَمَنٍ لَهُ","فَقَدْ أَسْلَفَ التُّجَّارُ فِيهِ وَأَسْلَمُوا"],["وَحَيَّ عَلَى يَوْمِ الْمَزِيدِ الَّذِي بِهِ","زِيَارَةُ رَبِّ الْعَرْشِ فَالْيَوْمُ مَوْسِمُ"],["وَحَيَّ عَلَى وَادٍ هُنَالِكَ أَفْيَحٍ","وَتُرْبَتُهُ مِنْ أَذْفَرِ الْمِسْكِ أَعْظَمُ"],["مَنَابِرُ مِنْ نُورٍ هُنَاكَ وَفِضَّةٍ","وَمِنْ خَالِصِ الْعِقْيَانِ لَا تَتَفَصَّمُ"],["وَمِنْ حَوْلِهَا كُثْبَانُ مِسْكٍ مَقَاعِدٌ","لِمَنْ دُونَهُمْ هَذَا الْعَطَاءُ الْمُفَخَّمُ"],["يَرَوْنَ بِهِ الرَّحْمَنَ جَلَّ جَلَالُهُ","كَرُؤْيَةِ بَدْرِ التَّمِّ لَا يُتَوَهَّمُ"],["وَكَالشَّمْسِ صَحْوًا لَيْسَ مِنْ دُونِ أُفْقِهَا","سَحَابٌ وَلَا غَيْمٌ هُنَاكَ يُغَيِّمُ"],["فَبَيْنَا هُمُ فِي عَيْشِهِمْ وَسُرُورِهِمْ","وَأَرْزَاقُهُمْ تُجْرَى عَلَيْهِمْ وَتُقْسَمُ"],["إِذَا هُمْ بِنُورٍ سَاطِعٍ قَدْ بَدَا لَهُمْ","وَقَدْ رَفَعُوا أَبْصَارَهُمْ فَإِذَا هُمُ"],["بِرَبِّهِمُ مِنْ فَوْقِهِمْ قَائِلٌ لَهُمْ","سَلَامٌ عَلَيْكُمْ طِبْتُمُ وَنَعِمْتُمُ"],["سَلَامٌ عَلَيْكُمْ يَسْمَعُونَ جَمِيعُهُمْ","بِآذَانِهِمْ تَسْلِيمَهُ إِذْ يُسَلِّمُ"],["يَقُولُ سَلُونِي مَا اشْتَهَيْتُمْ فَكُلُّ مَا","تُرِيدُونَ عِنْدِي إِنَّنِي أَنَا أَرْحَمُ"],["فَقَالُوا جَمِيعًا نَحْنُ نَسْأَلُكَ الرِّضَا","فَأَنْتَ الَّذِي تُولِي الْجَمِيلَ وَتَرْحَمُ"],["فَيُعْطِيهِمُ هَذَا وَيُشْهِدُ جَمْعَهُمْ","عَلَيْهِ تَعَالَى اللَّهُ فَاللَّهُ أَكْرَمُ"],["فَبِاللَّهِ مَا عُذْرُ امْرِئٍ هُوَ مُؤْمِنٌ","بِهَذَا وَلَا يَسْعَى لَهُ وَيُقَدِّمُ"],["وَلَكِنَّمَا التَّوْفِيقُ بِاللَّهِ إِنَّهُ","يَخُصُّ بِهِ مَنْ شَاءَ فَضْلًا وَيُنْعِمُ"],["فَيَا بَائِعًا هَذَا بِبَخْسٍ مُعَجَّلٍ","كَأَنَّكَ لَا تَدْرِي بَلَى سَوْفَ تَعْلَمُ"],["فَقَدِّمْ فَدَتْكَ النَّفْسُ نَفْسَكَ إِنَّهَا","هِيَ الثَّمَنُ الْمَبْذُولُ حِينَ تُسَلَّمُ"],["وَخُضْ غَمَرَاتِ الْمَوْتِ وَارْقَ مَعَارِجَ الْـ","ـمَحَبَّةِ فِي مَرْضَاتِهِمْ تَتَسَنَّمُ"],["وَسَلِّمْ لَهُمْ مَا عَاقَدُوكَ عَلَيْهِ إِنْ","تُرِدْ مِنْهُمُ أَنْ يَبْذُلُوا وَيُسَلِّمُوا"],["فَمَا ظَفِرَتْ بِالْوَصْلِ نَفْسٌ مَهِينَةٌ","وَلَا فَازَ عَبْدٌ بِالْبَطَالَةِ يَنْعَمُ"],["وَإِنْ تَكُ قَدْ عَاقَتْكَ سُعْدَى فَقَلْبُكَ الْـ","ـمُعَنَّى رَهِينٌ فِي يَدَيْهَا مُسَلَّمُ"],["وَقَدْ سَاعَدَتْ بِالْوَصْلِ غَيْرَكَ فَالْهَوَى","لَهَا مِنْكَ وَالْوَاشِي بِهَا يَتَنَعَّمُ"],["فَدَعْهَا وَسَلِّ النَّفْسَ عَنْهَا بِجَنَّةٍ","مِنَ الْعِلْمِ فِي رَوْضَاتِهَا الْحَقُّ يَبْسِمُ"],["وَقَدْ ذُلِّلَتْ مِنْهَا الْقُطُوفُ فَمَنْ يُرِدْ","جَنَاهَا يَنَلْهُ كَيْفَ شَاءَ وَيَطْعَمُ"],["وَقَدْ فُتِحَتْ أَبْوَابُهَا وَتَزَيَّنَتْ","لِخُطَّابِهَا فَالْحُسْنُ فِيهَا مُقَسَّمُ"],["وَقَدْ طَابَ مِنْهَا نُزْلُهَا وَنَزِيلُهَا","فَطُوبَى لِمَنْ حَلُّوا بِهَا وَتَنَعَّمُوا"],["أَقَامَ عَلَى أَبْوَابِهَا دَاعِيَ الْهُدَى","هَلُمُّوا إِلَى دَارِ السَّعَادَةِ تَغْنَمُوا"],["وَقَدْ غَرَسَ الرَّحْمَنُ فِيهَا غِرَاسَهُ","مِنَ النَّاسِ وَالرَّحْمَنُ بِالْخَلْقِ أَعْلَمُ"],["وَمَنْ يَغْرِسِ الرَّحْمَنُ فِيهَا فَإِنَّهُ","سَعِيدٌ وَإِلَّا فَالشَّقَاءُ مُحَتَّمُ"]],"secs":{"1":"القصيدة الميمية","27":"مشهد الحجيج","89":"انتفاضة البعث","129":"أمنيات","143":"سبيل النجاة","166":"بلاد الأشواق"}}],"sharh":false};
